<?php

declare(strict_types=1);

namespace App\Core\Backups\Destinations;

use RuntimeException;

/**
 * Somewhere a backup file can be sent. File names are always generated by the backup service
 * (see Destination::validName()), never taken from users.
 */
abstract class Destination
{
    /** Backup files the app creates and may therefore also prune. */
    public const NAME_PATTERN = '/^itm-backup-\d{8}-\d{6}\.sql\.gz(\.enc)?$/';

    /** Throwaway file used by test(). */
    private const PROBE_PATTERN = '/^\.itm-backup-test-[a-f0-9]{12}$/';

    /**
     * Sends a local file; returns where it ended up (for the run log).
     */
    abstract public function put(string $localPath, string $name): string;

    abstract public function delete(string $name): void;

    /**
     * Names of the files in the destination folder (backups only is not guaranteed; callers filter).
     *
     * @return list<string>
     */
    abstract public function list(): array;

    /**
     * Proves the destination works end to end: writes a small file, finds it, deletes it. Throws on failure.
     */
    public function test(): void
    {
        $name = '.itm-backup-test-' . bin2hex(random_bytes(6));
        $tmp  = tempnam(sys_get_temp_dir(), 'bkt');

        if ($tmp === false || file_put_contents($tmp, 'ITM backup connection test ' . date('c')) === false) {
            throw new RuntimeException('Could not create a temporary test file.');
        }

        try {
            $this->put($tmp, $name);
            $this->delete($name);
        } finally {
            @unlink($tmp);
        }

        $this->list();
    }

    protected static function validName(string $name): string
    {
        if (preg_match(self::NAME_PATTERN, $name) !== 1 && preg_match(self::PROBE_PATTERN, $name) !== 1) {
            throw new RuntimeException('Refusing to use an unexpected file name.');
        }

        return $name;
    }

    /**
     * Trims a folder setting to clean "a/b" form, rejecting anything that could escape it.
     */
    protected static function cleanFolder(string $folder): string
    {
        $parts = array_values(array_filter(preg_split('#[\\\\/]+#', trim($folder)) ?: [], static fn ($p) => $p !== ''));

        foreach ($parts as $p) {
            if ($p === '.' || $p === '..') {
                throw new RuntimeException('The folder cannot contain "." or "..".');
            }
        }

        return implode('/', $parts);
    }
}
